namespace Challenge;public interface IRemote{Task<string> FetchAsync(string id,CancellationToken ct);}public sealed class Aggregator(IRemote remote,int maxConcurrency=4){public async Task<IReadOnlyList<string>> FetchAllAsync(IReadOnlyList<string> ids,CancellationToken ct=default){using var gate=new SemaphoreSlim(maxConcurrency);var output=new string[ids.Count];var tasks=ids.Select(async(id,i)=>{await gate.WaitAsync(ct);try{output[i]=await remote.FetchAsync(id,ct);}finally{gate.Release();}});await Task.WhenAll(tasks);return output;}}
